public class Circle implements Cloneable {
    private int radius;
    private int[] pattern;

    @Override public Circle clone() {
        Circle c = (Circle) super.clone();   // shallow field copy
        c.pattern = pattern.clone();         // deep-copy mutable fields
        return c;
    }
